const raw = $env.AEGIS_PBC_REQUEST_RECIPIENTS_JSON;
if ($env.AEGIS_PBC_EMAIL_ENABLED !== 'true' || !raw) throw new Error('AEGIS_PBC_EMAIL_ENABLED=true and AEGIS_PBC_REQUEST_RECIPIENTS_JSON are required; refusing client notification');
let recipients;
try { recipients = JSON.parse(raw); } catch (e) { throw new Error('AEGIS_PBC_REQUEST_RECIPIENTS_JSON must be valid JSON'); }
return $input.all().map(item => {
  const cfg = recipients[item.json.engagement_id];
  if (!cfg || !Array.isArray(cfg.to) || cfg.to.length === 0 || cfg.to.some(x => !String(x).includes('@'))) throw new Error(`No valid recipient mapping for ${item.json.engagement_id}`);
  const x = item.json;
  return { json: { ...x, to_email: cfg.to.join(','), cc_email: (cfg.cc || []).join(','),
    subject: `[Aegis] PBC 추가자료 요청 ${x.rule_id} / ${x.engagement_id}`,
    body: `감사자료 추가 요청입니다.\n\nEngagement: ${x.engagement_id}\n요청 유형: ${x.rule_id}\n요청 사유: ${x.request_reason}\n원본 파일: ${x.file_name || '확인 필요'}\n\n보안 데이터룸을 통해 자료를 업로드해 주세요. 이 메일에 고객자료를 직접 회신하지 마세요.` } };
});

